#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# gh secret/variable 依赖当前目录解析仓库；统一切到仓库根目录。
cd "$(git rev-parse --show-toplevel)" || { echo "请在 git 仓库内运行本脚本" >&2; exit 1; }

# 只持久化公开值，密钥不落盘；权限 600。
ENV_FILE="${ENV_FILE:-$HOME/.config/yunhefc/ci-external.env}"
umask 077
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE"
chmod 600 "$ENV_FILE"

GH_READY=0
OWNER=""
REPO=""

banner "云河FC 镜像流水线外部前置"

stage "预检：gh 与仓库权限"
say "本 wizard 只配置镜像流水线：ACR、GitHub Variables/Secrets、分支保护与 production Environment。"
say "密钥只通过 gh secret set 写入 GitHub，不写入本地文件；ECS 侧前置不在本范围。"
step "确认当前目录属于 zhouyacheng/yunhefc（脚本会自动切到仓库根目录）。"
note "分支保护和 Environment 需要仓库管理员权限。"

if ! command -v gh >/dev/null 2>&1; then
  if command -v brew >/dev/null 2>&1; then
    if confirm "未检测到 gh，现在用 Homebrew 安装？"; then
      brew install gh || warn "gh 安装失败，可稍后手动安装：https://cli.github.com/"
    fi
  else
    warn "未检测到 gh 和 Homebrew；请手动安装：https://cli.github.com/"
    pause "安装完成后按 Enter 继续"
  fi
fi

if command -v gh >/dev/null 2>&1; then
  if ! gh auth status >/dev/null 2>&1; then
    step "运行 gh auth login：选择 GitHub.com → HTTPS → Login with a web browser。"
    gh auth login || warn "gh auth login 未完成；后续写入会跳过并列出待办。"
  fi
  if gh auth status >/dev/null 2>&1; then
    GH_READY=1
  fi
fi

repo_nwo=""
if (( GH_READY )); then
  repo_nwo="$(gh repo view --json nameWithOwner -q .nameWithOwner 2>/dev/null || true)"
fi
if [[ -z "$repo_nwo" ]]; then
  remote_url="$(git remote get-url origin 2>/dev/null || true)"
  case "$remote_url" in
    git@github.com:*) repo_nwo="${remote_url#git@github.com:}" ;;
    https://github.com/*) repo_nwo="${remote_url#https://github.com/}" ;;
  esac
  repo_nwo="${repo_nwo%.git}"
fi
if [[ "$repo_nwo" != */* ]]; then
  warn "无法解析 owner/repo；请检查 git remote origin。"
  pause "修正后按 Enter 继续"
else
  OWNER="${repo_nwo%%/*}"
  REPO="${repo_nwo##*/}"
  write_env REPO_NWO "$OWNER/$REPO"
  say "仓库：$OWNER/$REPO"
fi

if (( GH_READY )) && [[ -n "$OWNER" ]]; then
  gh repo set-default "$OWNER/$REPO" >/dev/null 2>&1 || true
  admin="$(gh api "repos/$OWNER/$REPO" --jq '.permissions.admin' 2>/dev/null || echo false)"
  if [[ "$admin" != "true" ]]; then
    warn "当前 gh 账号不是该仓库 admin；分支保护与 Environment 步骤会失败。"
  else
    say "gh 已登录且具备 admin 权限。"
  fi
fi

stage "ACR 实例与命名空间"
open_url "https://cr.console.aliyun.com/"
step "选择与 ECS 同地域的 ACR 实例（个人版或企业版）。"
step "设置/确认实例访问凭证，并创建命名空间（如 yunhefc）。"
step "在实例概览页复制公网 registry 端点，形如 registry.cn-hangzhou.aliyuncs.com。"
note "GitHub runner 走公网；不要使用 VPC 专用端点。"
while true; do
  ask ACR_REGISTRY "Registry 端点："
  ACR_REGISTRY="${ACR_REGISTRY#https://}"
  ACR_REGISTRY="${ACR_REGISTRY#http://}"
  ACR_REGISTRY="${ACR_REGISTRY%/}"
  if [[ "$ACR_REGISTRY" =~ ^[a-z0-9][a-z0-9.-]*(:[0-9]+)?$ ]]; then
    break
  fi
  warn "格式不对：只填 registry 主机名（可带端口），不要带 scheme 或路径。"
done
while true; do
  ask ACR_NAMESPACE "命名空间："
  if [[ "$ACR_NAMESPACE" =~ ^[a-z][a-z0-9-]{1,29}$ ]]; then
    break
  fi
  warn "格式不对：2–30 位小写字母/数字/连字符，且以字母开头。"
done
write_env ACR_REGISTRY "$ACR_REGISTRY"
write_env ACR_NAMESPACE "$ACR_NAMESPACE"
set_var ACR_REGISTRY "$ACR_REGISTRY"
set_var ACR_NAMESPACE "$ACR_NAMESPACE"

stage "ACR 双仓库"
open_url "https://cr.console.aliyun.com/"
step "在刚创建的命名空间下创建两个私有仓库，名称必须完全一致："
step "  yunhefc-backend"
step "  yunhefc-nginx"
note "CI 会推送 sha-<7> 不可变 tag；不要创建 latest。"
pause "两个仓库创建完成后按 Enter 继续"

stage "ACR 写权限账号"
step "个人版：在实例的访问凭证页设置/查看固定密码。"
step "企业版：创建仅含 ACR 推送/拉取权限的 RAM 用户，不要使用主账号。"
note "用户名和密码只写入 GitHub Secrets，不写入本地文件。"
ask ACR_USERNAME "ACR 用户名："
ask_secret ACR_PASSWORD "ACR 密码（输入不回显）："
set_secret ACR_USERNAME "$ACR_USERNAME"
set_secret ACR_PASSWORD "$ACR_PASSWORD"

if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1 && [[ -n "$ACR_USERNAME" && -n "$ACR_PASSWORD" ]]; then
  tmp_docker_cfg="$(mktemp -d)"
  if printf '%s' "$ACR_PASSWORD" \
      | DOCKER_CONFIG="$tmp_docker_cfg" docker login "$ACR_REGISTRY" \
          -u "$ACR_USERNAME" --password-stdin >/dev/null 2>&1; then
    say "docker login 校验通过。"
  else
    warn "docker login 失败：确认 Registry 端点、账号与推送权限（可稍后重试）。"
  fi
  rm -rf "$tmp_docker_cfg"
fi

stage "PUBLIC_DOMAIN"
say "用于 nginx 镜像构建期的 VITE_WEB_URL / VITE_ADMIN_URL。"
note "必须是裸域名（如 example.com），不带 https://、www. 或路径；改域名需重建镜像。"
while true; do
  ask PUBLIC_DOMAIN "裸域名："
  if [[ "$PUBLIC_DOMAIN" =~ ^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$ ]] \
      && [[ "$PUBLIC_DOMAIN" != www.* ]]; then
    break
  fi
  warn "格式不对：使用小写裸域名，不要 www. 前缀、scheme 或路径。"
done
write_env PUBLIC_DOMAIN "$PUBLIC_DOMAIN"
set_var PUBLIC_DOMAIN "$PUBLIC_DOMAIN"

stage "main 分支保护"
open_url "https://github.com/$OWNER/$REPO/settings/branches"
step "Add branch protection rule（或 Ruleset），目标分支 main。"
step "勾选 Require a pull request before merging；Required approvals 设为 0。"
step "勾选 Require status checks to pass，添加 prototype、backend、frontend。"
step "勾选 Do not allow force pushes 与 Do not allow deletions。"
warn "若三项检查在列表中不可选：先推一个分支并开 PR 跑一次 ci，再回来配置。"
pause "配置完成后按 Enter 校验"

if (( GH_READY )) && [[ -n "$OWNER" ]]; then
  if contexts="$(gh api "repos/$OWNER/$REPO/branches/main/protection" \
      --jq '.required_status_checks.contexts[]?' 2>/dev/null)"; then
    for ctx in prototype backend frontend; do
      if grep -qx "$ctx" <<<"$contexts"; then
        say "✓ 必需检查 $ctx"
      else
        warn "缺少必需检查：$ctx"
      fi
    done
  else
    warn "未检测到经典分支保护；若使用 Rulesets，请到 .../settings/rules 核对。"
  fi
fi

stage "production Environment"
open_url "https://github.com/$OWNER/$REPO/settings/environments"
step "New environment → 名称 production。"
step "Required reviewers 添加至少 1 人（或团队）。"
step "Deployment branches and tags → Selected branches → 添加 main。"
warn "required reviewer 与触发者权限需兼容；单人仓库先用自己/团队验证。"
pause "配置完成后按 Enter 校验"

if (( GH_READY )) && [[ -n "$OWNER" ]]; then
  if gh api "repos/$OWNER/$REPO/environments/production" >/dev/null 2>&1; then
    say "✓ 已检测到 production Environment"
    branches="$(gh api "repos/$OWNER/$REPO/environments/production/deployment-branch-policies" \
      --jq '.branch_policies[].name' 2>/dev/null || true)"
    if grep -qx "main" <<<"$branches"; then
      say "✓ deployment branch 仅 main"
    else
      warn "未检测到 main 的 deployment branch 策略（或使用了其他规则）。"
    fi
  else
    warn "未检测到 production Environment。"
  fi
fi

stage "核对与下一步"
if (( GH_READY )); then
  vars_out="$(gh variable list 2>/dev/null || true)"
  secrets_out="$(gh secret list 2>/dev/null || true)"
  for name in ACR_REGISTRY ACR_NAMESPACE PUBLIC_DOMAIN; do
    if grep -q "^${name}[[:space:]]" <<<"$vars_out"; then
      say "✓ variable $name"
    else
      warn "缺少 variable $name"
    fi
  done
  for name in ACR_USERNAME ACR_PASSWORD; do
    if grep -q "^${name}[[:space:]]" <<<"$secrets_out"; then
      say "✓ secret $name"
    else
      warn "缺少 secret $name"
    fi
  done
else
  warn "gh 不可用：请按 finish 中的待办手动写入 Variables/Secrets。"
fi
step "开 PR 到 main，确认 prototype / backend / frontend 三项检查为绿。"
step "合并后等待 ci 的 e2e 与 images；在 ACR 两个仓库确认同一 sha-<7>。"
step "校验分支保护：直接 git push origin main 应被拒绝。"
note "deploy 仍需 ECS_*、ECS_SSH_KEY、ECS_KNOWN_HOSTS、DEPLOY_WEBHOOK_URL 与 ECS 运行时前置，不在本 wizard 范围。"
pause "按 Enter 结束"

finish
